 jsonb_build_array('استقرار ناظر تازه‌استخدام‌شده مستقیماً در جبهه کاری بدون دوره آشناسازی/همراهی', 'فرض این‌که تجربه عمومی قبلی جایگزین آشنایی با مشخصات فنی خاص این پروژه است'),
