 'رویه مدیریت ریسک نوسان ارز در پروژه‌های EPC (Currency Exposure Management)'),

('project_director','GENERAL','مدیریت جانشین‌پروری برای نقش‌های کلیدی پروژه','L2',
 'چرا برنامه‌ریزی جانشین‌پروری (Succession Planning) برای نقش‌های کلیدی فنی/مدیریتی پروژه‌های بلندمدت اهمیت راهبردی دارد؟',
 'خروج ناگهانی یک نفر در نقش کلیدی (مثل مهندس ارشد یا مدیر کنترل پروژه) بدون جانشین آماده می‌تواند دانش حیاتی پروژه را از دست بدهد و پیوستگی تصمیم‌گیری را مختل کند؛ برای نقش‌های حیاتی، شناسایی و آماده‌سازی زودهنگام حداقل یک جانشین بالقوه داخلی را در برنامه مدیریت منابع انسانی پروژه الزامی می‌دانم.',
 jsonb_build_array('ریسک از دست رفتن دانش حیاتی و اختلال پیوستگی تصمیم‌گیری با خروج ناگهانی نقش کلیدی', 'شناسایی زودهنگام جانشین بالقوه داخلی برای نقش‌های حیاتی پروژه', 'آماده‌سازی فعال (نه صرفاً شناسایی اسمی) جانشین از طریق مسئولیت‌های تدریجی', 'یکپارچگی برنامه جانشین‌پروری با برنامه کلی منابع انسانی پروژه'),
 jsonb_build_array('تفکر راهبردی بلندمدت درباره تداوم پروژه فراتر از مدیریت روزمره منابع انسانی'),
 jsonb_build_array('عدم برنامه‌ریزی جانشین‌پروری تا زمان بروز خروج واقعی و ناگهانی یک نقش کلیدی', 'شناسایی صرفاً اسمی جانشین بدون آماده‌سازی عملی از طریق مسئولیت تدریجی'),
 'رویه برنامه‌ریزی جانشین‌پروری پروژه (Project Succession Planning)'),

('project_director','SCENARIO','واکنش به رقابت منابع بین دو زیرپروژه با اولویت راهبردی برابر','L3',
 'دو زیرپروژه هم‌زمان تحت مدیریت شما، هر دو با اولویت راهبردی نسبتاً برابر، درخواست تخصیص یک منبع کمیاب (مثلاً تیم تخصصی خاص) دارند و ظرفیت کافی برای هر دو هم‌زمان وجود ندارد. چگونه تصمیم می‌گیرید؟',
 'به‌جای تصمیم صرفاً شهودی، معیارهای عینی (اثر تاخیر بر مسیر بحرانی هر زیرپروژه، ریسک قراردادی هر تاخیر، و هزینه فرصت) را برای هر دو گزینه محاسبه و مقایسه می‌کنم؛ تصمیم نهایی و منطق آن را به‌طور شفاف با مدیران هر دو زیرپروژه در میان می‌گذارم تا از تصور ترجیح شخصی جلوگیری شود.',
 jsonb_build_array('استفاده از معیارهای عینی (اثر بر مسیر بحرانی، ریسک قراردادی، هزینه فرصت) برای تصمیم تخصیص منابع', 'عدم تصمیم‌گیری صرفاً شهودی یا بر مبنای ترجیح شخصی', 'شفافیت کامل درباره منطق تصمیم با مدیران هر دو زیرپروژه', 'مستندسازی تصمیم و معیارهای آن برای مرجع آینده'),
 jsonb_build_array('رویکرد تحلیلی و شفاف به‌جای تصمیم‌گیری که می‌تواند به‌عنوان ترجیح شخصی یا سیاسی تلقی شود'),
 jsonb_build_array('تصمیم‌گیری تخصیص منابع بر مبنای روابط شخصی یا فشار بلندتر مدیر یک زیرپروژه', 'عدم شفافیت درباره منطق تصمیم که باعث بی‌اعتمادی مدیران زیرپروژه‌ها می‌شود'),
 'رویه تخصیص منابع محدود بین پروژه‌های هم‌اولویت (Portfolio Resource Allocation)'),

('project_director','HSE','مدیریت ریسک راهبردی فرهنگ گزارش‌دهی ناقص حوادث جزئی','L4',
 'تحلیل داده چند ماهه نشان می‌دهد نرخ گزارش‌دهی نزدیک‌به‌حادثه (Near-Miss) در پروژه به‌طور غیرعادی پایین است، در حالی که نرخ حوادث واقعی نرمال به نظر می‌رسد. چرا این الگو خودش یک نشانه هشدار راهبردی است و چه اقدامی انجام می‌دهید؟',
 'نرخ پایین غیرعادی گزارش نزدیک‌به‌حادثه معمولاً نشانه فرهنگ ترس از گزارش‌دهی (نه واقعاً ایمن‌تر بودن کار) است که خطرناک‌تر از نرخ بالای گزارش‌دهی شفاف است؛ بررسی می‌کنم آیا پرسنل از پیامد گزارش‌دهی (تنبیه، انگ) می‌ترسند و اقدامات لازم برای ایجاد فرهنگ گزارش‌دهی بدون تنبیه (Just Culture) را در سطح راهبردی پروژه اجرا می‌کنم.',
 jsonb_build_array('تشخیص نرخ پایین غیرعادی گزارش نزدیک‌به‌حادثه به‌عنوان نشانه فرهنگ ترس، نه ایمنی واقعی', 'بررسی ترس پرسنل از پیامد گزارش‌دهی (تنبیه، انگ) به‌عنوان علت محتمل', 'اجرای اقدامات ایجاد فرهنگ گزارش‌دهی بدون تنبیه (Just Culture) در سطح راهبردی', 'پایش روند گزارش‌دهی پس از اقدامات اصلاحی برای سنجش اثربخشی'),
 jsonb_build_array('تفسیر ضدشهودی درست داده HSE (نرخ پایین گزارش به‌عنوان هشدار، نه اطمینان‌بخشی) که نشانه بلوغ راهبردی در تفسیر داده ایمنی است'),
 jsonb_build_array('تفسیر نرخ پایین گزارش نزدیک‌به‌حادثه به‌عنوان نشانه مثبت ایمنی بدون بررسی علت واقعی', 'عدم اقدام راهبردی برای اصلاح فرهنگ ترس از گزارش‌دهی'),
 'اصول فرهنگ ایمنی بدون تنبیه (Just Culture) / رویه تحلیل الگوی گزارش‌دهی نزدیک‌به‌حادثه'),

('project_director','JUDGMENT','قضاوت درباره ادامه همکاری با کارفرمای دارای سابقه پرداخت نامنظم','L4',
 'کارفرمای فعلی پروژه سابقه پرداخت‌های نامنظم (اما نه کاملاً قطع‌شده) دارد که فشار نقدینگی قابل‌توجهی بر شرکت پیمانکار ایجاد کرده است. چگونه به‌عنوان مدیر پروژه ارشد این وضعیت راهبردی را مدیریت می‌کنید؟',
 'به‌جای تحمل خاموش وضعیت یا تهدید فوری به توقف کار، مستندسازی دقیق و منظم هر تاخیر پرداخت را آغاز می‌کنم، مسیر رسمی اطلاع‌رسانی طبق بندهای قراردادی (اخطار رسمی تاخیر پرداخت) را دنبال می‌کنم و همزمان گزینه‌های مدیریت نقدینگی داخلی شرکت را با مدیریت ارشد سازمان در میان می‌گذارم تا تصمیم راهبردی (ادامه با احتیاط بیشتر یا اعمال حقوق قراردادی) آگاهانه گرفته شود.',
 jsonb_build_array('مستندسازی دقیق و منظم هر تاخیر پرداخت از ابتدا', 'پیگیری مسیر رسمی اطلاع‌رسانی طبق بندهای قراردادی (اخطار رسمی)', 'هماهنگی گزینه‌های مدیریت نقدینگی داخلی با مدیریت ارشد سازمان', 'تصمیم راهبردی آگاهانه بر مبنای تحلیل کامل، نه واکنش احساسی یا تحمل خاموش'),
 jsonb_build_array('مدیریت فعال و مستند یک ریسک راهبردی حساس به‌جای تحمل خاموش آن تا بحران کامل یا واکنش تند بی‌مقدمه'),
 jsonb_build_array('تحمل خاموش تاخیرهای پرداخت بدون مستندسازی یا اخطار رسمی', 'تهدید فوری و بدون مقدمه به توقف کامل کار بدون طی مسیر رسمی قراردادی'),
 'شرایط عمومی پیمان FIDIC (حقوق پیمانکار در تاخیر پرداخت) / رویه مدیریت ریسک راهبردی کارفرما');
